package com.bautruc.ecommerce.payment.api.response;import java.time.Instant;import com.bautruc.ecommerce.payment.domain.*;public record PaymentResponse(Long id,Long orderId,PaymentStatus status,long amount,String checkoutUrl,String qrCode,Instant expiresAt,Instant paidAt){public static PaymentResponse from(Payment p){return new PaymentResponse(p.getId(),p.getOrderId(),p.getStatus(),p.getAmount(),p.getCheckoutUrl(),p.getQrCode(),p.getExpiresAt(),p.getPaidAt());}}
